CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(255) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, company VARCHAR(255) DEFAULT '', role VARCHAR(100) DEFAULT 'Guest', phone VARCHAR(50) DEFAULT '', units_balance INTEGER DEFAULT 0, balance_usd DECIMAL(10,2) DEFAULT 0.00, status VARCHAR(50) DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
